// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
        LogFile log = new LogFile();
        c.SetLogFile(address(log));
        c.SetMinSum(0);
        c.Initialized();
    }

    function testFuzz_property(address actor, uint64 amount) public {
        vm.assume(actor != address(0));
        vm.assume(amount > 0);
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Deposit{value: amount}();
        assertTrue(c.balances(actor) == amount);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function test(uint256 v) public {
        require(v > 0);
        require(address(this).balance >= v);
        c.Deposit{value: v}();
        assert(c.balances(address(this)) >= v);
    }

    receive() external payable {}
    fallback() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount) public payable {
        require(address(this).balance >= amount, "insufficient test balance");
        bool reverted;
        try c.Deposit{value: amount}() { reverted = false; } catch { reverted = true; }
        assert(!reverted);
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount) public payable {
        require(amount > 0);
        require(address(this).balance >= amount);
        uint balBefore = address(c).balance;
        bool reverted;
        try c.Deposit{value: amount}() { reverted = false; } catch { reverted = true; }
        assert(!reverted && address(c).balance == balBefore + amount);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint a, uint b) public payable {
        require(a <= b);
        require(a + b >= a);
        require(address(this).balance >= a + b);
        bool rev1;
        try c.Deposit{value: a}() { rev1 = false; } catch { rev1 = true; }
        bool rev2;
        try c.Deposit{value: b}() { rev2 = false; } catch { rev2 = true; }
        assert(!rev1 && !rev2);
    }
    receive() external payable {}
}
